GallerySection _sectionFor(String id) {
  if (id == "overview") return GallerySection.overview;
  if (id.startsWith("charts-")) return GallerySection.charts;
  if (id.startsWith("template-") ||
      id == "auth-screen" ||
      id == "auth-2fa" ||
      id == "auth-otp" ||
      id == "forgot-password" ||
      id == "data-table" ||
      id == "calendar") {
    return GallerySection.templates;
  }
  if (id.startsWith("behaviour-")) return GallerySection.behaviours;
  if (id.startsWith("assets-")) return GallerySection.assets;
  if (id.startsWith("icons-")) return GallerySection.icons;
  if (id.startsWith("docs-")) return GallerySection.docs;
  if (id.startsWith("store-")) return GallerySection.store;
  if (id == "support") return GallerySection.docs;
  if (id.startsWith("lsp-")) return GallerySection.components;
  return GallerySection.components;
}

String _fallbackLabel(String id) {
  final words = id.replaceFirst(RegExp(r'^lsp-'), '').split('-');
  return words
      .where((word) => word.isNotEmpty)
      .map((word) => word[0].toUpperCase() + word.substring(1))
      .join(' ');
}

